String[] results = new String[3];

Thread t1 = new Thread(() -> {
    // simulate fetch
    try { Thread.sleep(300); } catch (InterruptedException e) { Thread.currentThread().interrupt(); return; }
    results[0] = "User: Priya";
}, "FetchUser");

Thread t2 = new Thread(() -> {
    try { Thread.sleep(500); } catch (InterruptedException e) { Thread.currentThread().interrupt(); return; }
    results[1] = "Orders: [#101, #102]";
}, "FetchOrders");

Thread t3 = new Thread(() -> {
    try { Thread.sleep(200); } catch (InterruptedException e) { Thread.currentThread().interrupt(); return; }
    results[2] = "Inventory: 150 units";
}, "FetchInventory");

t1.start(); t2.start(); t3.start();

t1.join(); t2.join(); t3.join();
// All three done — safe to combine
System.out.println(results[0] + ' | ' + results[1] + ' | ' + results[2]);
// Total time: ~500ms (parallel) vs ~1000ms (sequential). Note: String[] is used for results to allow writing from Runnable lambda. In production, use AtomicReference or CompletableFuture.

